bg_val = 8

def get_all_h_gaps(grid):
    h, w = len(grid), len(grid[0])
    gaps_by_row = {}
    for r in range(h):
        row = grid[r]
        markers = sorted([c for c in range(w) if row[c] != bg_val])
        row_gaps = []
        for i in range(len(markers)-1):
            left = markers[i] + 1
            right = markers[i+1] - 1
            if left <= right:
                row_gaps.append(list(range(left, right+1)))
        gaps_by_row[r] = row_gaps
    return gaps_by_row

def get_all_v_gaps(grid):
    h, w = len(grid), len(grid[0])
    gaps_by_col = {}
    for c in range(w):
        col_vals = [grid[r][c] for r in range(h)]
        markers = sorted([r for r in range(h) if col_vals[r] != bg_val])
